/** Curated themes, in picker order. The first entry is the default. */
export const m3Themes: M3ThemeDef[] = [baseline, ocean, emerald, coral];

export const defaultThemeId = "baseline";

export function getTheme(id: string): M3ThemeDef | undefined {
  return m3Themes.find((t) => t.id === id);
}

/** All valid theme ids (for validation). */
export const themeIds = m3Themes.map((t) => t.id);

/** Flatten a scheme into the --md-* CSS custom property map. */
export function schemeToCssVars(scheme: M3ColorScheme): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [key, value] of Object.entries(scheme)) {
    // camelCase → kebab: primaryContainer → primary-container
    const kebab = key.replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase();
    out[`--md-${kebab}`] = value;
  }
  return out;
}
